from customerimporter import CustomerIdentification, ZipCode

def old_identification(id_type, id_number):
    if id_type == "D":
        if not all(c.isdigit() for c in id_number): raise RuntimeError("Invalid DNI number")
        n = int(id_number)
        if not (n >= 1 and n <= 99999999): raise RuntimeError("Invalid DNI number")
    elif id_type == "C":
        if not (len(id_number) >= 12 and len(id_number) <= 13): raise RuntimeError("Invalid CUIT number")
        if not (id_number[2] == "-" and id_number[-2] == "-"): raise RuntimeError("Invalid CUIT number")
        if not id_number[:2] in ["20","23","24","25","26","27","30","33","34"]: raise RuntimeError("Invalid CUIT number")
        if not id_number[-1].isdigit(): raise RuntimeError("Invalid CUIT number")
        if not all(c.isdigit() for c in id_number[3:-2]): raise RuntimeError("Invalid CUIT number")
    else:
        raise RuntimeError("Invalid identification type")
    return ("type=" + id_type, "number=" + id_number)

def old_zip(zip_code):
    if zip_code[0].isdigit():
        if not all(c.isdigit() for c in zip_code): raise RuntimeError("Invalid old zipcode")
        v = int(zip_code)
        if not (v >= 1000 and v <= 9999): raise RuntimeError("Invalid old zipcode")
    elif zip_code[0].isalpha():
        if len(zip_code) != 8: raise RuntimeError("Invalid new zipcode")
        part = zip_code[1:5]
        if not all(c.isdigit() for c in part): raise RuntimeError("Invalid new zipcode")
        if not (int(part) > 999): raise RuntimeError("Invalid new zipcode")
        if not all(c.isalpha() for c in zip_code[-3:]): raise RuntimeError("Invalid new zipcode")
        v = zip_code
    else:
        raise RuntimeError("Invalid identification type")
    return v

